H.background();
const deg = Math.max(5, Math.min(85, P.angle));
const hyp = Math.max(1, P.hyp);
const ang = deg * Math.PI / 180;
const v = H.plot2d({ xMin: -1, xMax: 11, yMin: -1, yMax: 10 });
v.grid(); v.axes();
const opp = hyp * Math.sin(ang);
const adj = hyp * Math.cos(ang);
const Ax = 0, Ay = 0, Bx = adj, By = 0, Cx = adj, Cy = opp;
v.path([[Ax, Ay], [Bx, By], [Cx, Cy]], { color: H.colors.accent, width: 3, close: true });
v.line(Bx, By, Bx, 0.5, { color: H.colors.sub, width: 1 });
v.line(Bx - 0.5, 0.5, Bx, 0.5, { color: H.colors.sub, width: 1 });
const sweep = (Math.sin(t * 1.2) * 0.5 + 0.5);
const apts = [];
for (let i = 0; i <= 24; i++) { const a = ang * (i / 24) * sweep; apts.push([0.9 * Math.cos(a), 0.9 * Math.sin(a)]); }
v.path(apts, { color: H.colors.warn, width: 2 });
v.dot(adj * (0.5 + 0.5 * Math.sin(t)), opp * (0.5 + 0.5 * Math.sin(t)), { r: 5, fill: H.colors.yellow });
v.text("θ", 1.2, 0.45, { color: H.colors.warn, size: 14 });
v.text("opp = " + opp.toFixed(2), adj + 0.2, opp / 2, { color: H.colors.good, size: 13 });
v.text("adj = " + adj.toFixed(2), adj / 2, -0.5, { color: H.colors.accent, size: 13 });
v.text("hyp = " + hyp.toFixed(2), adj / 2 - 0.6, opp / 2 + 0.4, { color: H.colors.accent2, size: 13 });
H.text("Right-triangle trig: SOH-CAH-TOA", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
